};

export default ProductForm;

import React, { useState, useEffect } from 'react';
import { 
  ProductType, 
  CostingMethod, 
  Product 
} from '../types';
import { 
  ITEM_CATEGORIES, 
  MANUFACTURERS, 
  UNITS_OF_MEASURE
} from '../constants';

interface ProductFormProps {
  onSave: (product: Product) => void;
  onCancel: () => void;
  existingProducts: Product[];
}

const ProductForm: React.FC<ProductFormProps> = ({ onSave, onCancel, existingProducts }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState<Partial<Product>>({
    type: ProductType.FABRICANTE,
    baseUnitOfMeasure: 'UD',
    inventoryPostingGroup: 'MERCADERÍA', 
    genProdPostingGroup: 'MERCADERÍA',
    vatProdPostingGroup: 'IVA21',        
    costingMethod: CostingMethod.FIFO,
    unitPrice: 0,
    unitCost: 0,
    dimensionCode: 'GASTOS',            
    dimensionValueCode: 'MATERIAL',
    valuePosting: 'Mismo código',
    description: ''
  });

  const [manufacturerRef, setManufacturerRef] = useState('');
  const [descriptionTouched, setDescriptionTouched] = useState(false);

  // Auto-generate ID (No.) based on sequential business rules
  useEffect(() => {
    let prefix = '';
    if (formData.type === ProductType.FABRICANTE && formData.manufacturerCode) {
      prefix = formData.manufacturerCode.substring(0, 3).toUpperCase();
    } else if (formData.type === ProductType.GENERICO && formData.itemCategoryCode) {
      prefix = `G${formData.itemCategoryCode.substring(0, 3).toUpperCase()}`;
    }

    if (prefix) {
      const matching = existingProducts.filter(p => p.no.startsWith(prefix));
      let nextNumber = 1;

      if (matching.length > 0) {
        const numbers = matching.map(p => {
          const numPart = p.no.substring(prefix.length);
          return parseInt(numPart, 10) || 0;
        });
        nextNumber = Math.max(...numbers) + 1;
      }

      const formattedNumber = nextNumber.toString().padStart(4, '0');
      setFormData(prev => ({ ...prev, no: `${prefix}${formattedNumber}` }));
    } else {
      setFormData(prev => ({ ...prev, no: '' }));
    }
  }, [formData.type, formData.manufacturerCode, formData.itemCategoryCode, existingProducts]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;

    let processedValue: any = value;
    if (name === 'description') {
      processedValue = value.toUpperCase();
    }
    if (name === 'unitPrice' || name === 'unitCost') {
      processedValue = parseFloat(value) || 0;
    }

    setFormData(prev => ({ ...prev, [name]: processedValue }));
  };

  const validateAndSave = () => {
    const desc = formData.description?.trim();
    if (!desc) return;

    let finalDescription = desc;

    if (formData.type === ProductType.FABRICANTE && manufacturerRef) {
        const refSuffix = ` REF. ${manufacturerRef}`;
        if (!finalDescription.endsWith(refSuffix)) {
            finalDescription = `${finalDescription}${refSuffix}`;
        }
    }

    const completeProduct: Product = {
      ...formData as Product,
      description: finalDescription,
      manufacturerRef: manufacturerRef,
      inventoryPostingGroup: 'MERCADERÍA',
      vatProdPostingGroup: 'IVA21',
      dimensionCode: 'GASTOS'
    };

    onSave(completeProduct);
  };

  const isDescriptionValid = formData.description && formData.description.trim().length > 0;

  return (
    <div className="space-y-6">
      {/* Step Progress */}
      <div className="flex items-center justify-between mb-8 px-4">
        {[1, 2, 3].map((s) => (
          <div key={s} className="flex items-center">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold ${step === s ? 'bg-blue-600 text-white' : step > s ? 'bg-green-500 text-white' : 'bg-gray-200 text-gray-600'}`}>
              {s}
            </div>
            {s < 3 && <div className={`h-1 w-12 mx-2 ${step > s ? 'bg-green-500' : 'bg-gray-200'}`} />}
          </div>
        ))}
      </div>

      {step === 1 && (
        <div className="space-y-4">
          <h4 className="text-lg font-medium text-gray-700">Tipo de Producto</h4>
          <div className="grid grid-cols-2 gap-4">
            <button
              onClick={() => { setFormData({ ...formData, type: ProductType.FABRICANTE }); setStep(2); }}
              className={`p-6 border-2 rounded-xl text-left transition-all ${formData.type === ProductType.FABRICANTE ? 'border-blue-600 bg-blue-50' : 'border-gray-200 hover:border-blue-300'}`}
            >
              <div className="text-xl font-bold text-blue-700">Fabricante</div>
              <p className="text-sm text-gray-500 mt-1">Ligado a fabricante con referencia externa.</p>
            </button>
            <button
              onClick={() => { setFormData({ ...formData, type: ProductType.GENERICO }); setStep(2); }}
              className={`p-6 border-2 rounded-xl text-left transition-all ${formData.type === ProductType.GENERICO ? 'border-blue-600 bg-blue-50' : 'border-gray-200 hover:border-blue-300'}`}
            >
              <div className="text-xl font-bold text-blue-700">Genérico</div>
              <p className="text-sm text-gray-500 mt-1">Categoría general sin fabricante específico.</p>
            </button>
          </div>
        </div>
      )}

      {step === 2 && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Fabricante (Tabla 5720)</label>
            <select
              name="manufacturerCode"
              value={formData.manufacturerCode || ''}
              onChange={handleInputChange}
              className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
              disabled={formData.type === ProductType.GENERICO}
            >
              <option value="">Seleccione...</option>
              {MANUFACTURERS.map(m => <option key={m.code} value={m.code}>{m.code} - {m.name}</option>)}
            </select>
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Categoría (Tabla 5722)</label>
            <select
              name="itemCategoryCode"
              value={formData.itemCategoryCode || ''}
              onChange={handleInputChange}
              className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
            >
              <option value="">Seleccione...</option>
              {ITEM_CATEGORIES.map(c => <option key={c.code} value={c.code}>{c.code} - {c.description}</option>)}
            </select>
          </div>

          {formData.type === ProductType.FABRICANTE && (
            <div className="space-y-2 col-span-full">
              <label className="block text-sm font-semibold text-gray-600">Nro. de Referencia del Fabricante *</label>
              <input
                type="text"
                value={manufacturerRef}
                onChange={(e) => setManufacturerRef(e.target.value.toUpperCase())}
                placeholder="Ej: REF-12345"
                className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                required
              />
            </div>
          )}

          <div className="space-y-2 col-span-full">
            <label className="block text-sm font-semibold text-gray-600">No. (Código Correlativo Autogenerado)</label>
            <input
              type="text"
              readOnly
              value={formData.no || ''}
              placeholder="Seleccione fabricante/categoría..."
              className="w-full p-3 border border-blue-200 bg-blue-50 rounded text-blue-800 font-mono font-bold cursor-not-allowed"
            />
          </div>

          <div className="flex justify-between col-span-full mt-4">
            <button onClick={() => setStep(1)} className="px-6 py-2 border border-gray-300 rounded text-gray-600 hover:bg-gray-50">Atrás</button>
            <button 
              onClick={() => setStep(3)} 
              disabled={!formData.no || (formData.type === ProductType.FABRICANTE && !manufacturerRef)}
              className="px-6 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50"
            >
              Siguiente
            </button>
          </div>
        </div>
      )}

      {step === 3 && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2 col-span-full">
            <label className="block text-sm font-semibold text-gray-600">
              Descripción (MÁX 100 CARACTERES) <span className="text-red-500">*</span>
            </label>
            <input
              type="text"
              name="description"
              maxLength={100}
              value={formData.description || ''}
              onBlur={() => setDescriptionTouched(true)}
              onChange={handleInputChange}
              placeholder="DESCRIPCIÓN DEL PRODUCTO"
              className={`w-full p-2 border rounded focus:ring-2 focus:ring-blue-500 outline-none uppercase transition-colors ${
                descriptionTouched && !isDescriptionValid ? 'border-red-500 bg-red-50' : 'border-gray-300'
              }`}
              required
            />
            {descriptionTouched && !isDescriptionValid && (
              <p className="text-xs text-red-500 font-medium">La descripción es obligatoria.</p>
            )}
            {formData.type === ProductType.FABRICANTE && (
                <p className="text-xs text-gray-400 italic">Se añadirá automáticamente: " REF. {manufacturerRef}"</p>
            )}
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Unidad medida base</label>
            <select name="baseUnitOfMeasure" value={formData.baseUnitOfMeasure} onChange={handleInputChange} className="w-full p-2 border border-gray-300 rounded">
              {UNITS_OF_MEASURE.map(u => <option key={u} value={u}>{u}</option>)}
            </select>
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Precio venta</label>
            <input type="number" name="unitPrice" value={formData.unitPrice} onChange={handleInputChange} className="w-full p-2 border border-gray-300 rounded" />
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Coste unitario</label>
            <input type="number" name="unitCost" value={formData.unitCost} onChange={handleInputChange} className="w-full p-2 border border-gray-300 rounded" />
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Valoración existencias</label>
            <select name="costingMethod" value={formData.costingMethod} onChange={handleInputChange} className="w-full p-2 border border-gray-300 rounded">
              {Object.values(CostingMethod).map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>

          <div className="col-span-full bg-gray-50 p-4 rounded-lg border border-gray-200 mt-4">
            <h5 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-3">Información Automática (Configuración BC)</h5>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <span className="block text-[10px] text-gray-400 uppercase">Cód. Dimensión</span>
                <span className="text-sm font-bold text-gray-700">GASTOS</span>
              </div>
              <div>
                <span className="block text-[10px] text-gray-400 uppercase">Grup. Reg. Inventario</span>
                <span className="text-sm font-bold text-gray-700">MERCADERÍA</span>
              </div>
              <div>
                <span className="block text-[10px] text-gray-400 uppercase">IVA Prod.</span>
                <span className="text-sm font-bold text-gray-700">IVA21</span>
              </div>
            </div>
          </div>

          <div className="flex justify-between col-span-full mt-6 border-t pt-4">
            <button onClick={() => setStep(2)} className="px-6 py-2 border border-gray-300 rounded text-gray-600 hover:bg-gray-50">Atrás</button>
            <div className="space-x-4">
                <button onClick={onCancel} className="px-6 py-2 text-red-600 hover:bg-red-50 rounded">Cancelar</button>
                <button 
                  onClick={validateAndSave} 
                  disabled={!isDescriptionValid}
                  className="px-8 py-2 bg-blue-600 text-white font-bold rounded shadow-lg hover:bg-blue-700 disabled:opacity-50 disabled:bg-gray-400 transition-all"
                >
                  Crear Producto
                </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProductForm;

export enum ProductType {
  FABRICANTE = 'Fabricante',
  GENERICO = 'Genérico'
}

export enum CostingMethod {
  FIFO = 'FIFO',
  LIFO = 'LIFO',
  AVERAGE = 'Media',
  SPECIFIC = 'Específico',
  STANDARD = 'Estándar'
}

export interface ItemCategory {
  code: string;
  description: string;
}

export interface Manufacturer {
  code: string;
  name: string;
}

export interface Product {
  no: string;
  description: string;
  baseUnitOfMeasure: string;
  type: ProductType;
  inventoryPostingGroup: string;
  unitPrice: number;
  costingMethod: CostingMethod;
  unitCost: number;
  genProdPostingGroup: string;
  vatProdPostingGroup: string;
  manufacturerCode: string;
  itemCategoryCode: string;
  dimensionCode: string;
  dimensionValueCode: string;
  valuePosting: string;
  manufacturerRef?: string;
}

export enum UserRole {
  ADMIN = 'Administrador',
  TECNICO = 'Técnico',
  COMPRAS = 'Compras'
}

export interface RolePermissions {
  canCreateProduct: boolean;
  canManageMasterData: boolean;
}

export interface AppSettings {
  manufacturers: Manufacturer[];
  categories: ItemCategory[];
  unitsOfMeasure: string[];
  permissions: Record<UserRole, RolePermissions>;
}

import React, { useState } from 'react';
import { AppSettings, UserRole, Manufacturer, ItemCategory } from '../types';

interface SettingsProps {
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
  currentRole: UserRole;
}

const Settings: React.FC<SettingsProps> = ({ settings, onUpdateSettings, currentRole }) => {
  const [activeTab, setActiveTab] = useState<'manufacturers' | 'categories' | 'units' | 'roles'>('manufacturers');
  const [newItem, setNewItem] = useState({ code: '', name: '', desc: '', unit: '' });

  const isEditable = currentRole === UserRole.ADMIN;

  const handleTogglePermission = (role: UserRole, permission: 'canCreateProduct' | 'canManageMasterData') => {
    if (!isEditable) return;
    const newSettings = { ...settings };
    newSettings.permissions[role][permission] = !newSettings.permissions[role][permission];
    onUpdateSettings(newSettings);
  };

  const addItem = (type: 'manufacturer' | 'category' | 'unit') => {
    const newSettings = { ...settings };
    if (type === 'manufacturer' && newItem.code && newItem.name) {
      newSettings.manufacturers.push({ code: newItem.code.toUpperCase(), name: newItem.name.toUpperCase() });
    } else if (type === 'category' && newItem.code && newItem.desc) {
      newSettings.categories.push({ code: newItem.code.toUpperCase(), description: newItem.desc.toUpperCase() });
    } else if (type === 'unit' && newItem.unit) {
      newSettings.unitsOfMeasure.push(newItem.unit.toUpperCase());
    }
    onUpdateSettings(newSettings);
    setNewItem({ code: '', name: '', desc: '', unit: '' });
  };

  const removeItem = (type: 'manufacturer' | 'category' | 'unit', index: number) => {
    if (!isEditable) return;
    const newSettings = { ...settings };
    if (type === 'manufacturer') newSettings.manufacturers.splice(index, 1);
    if (type === 'category') newSettings.categories.splice(index, 1);
    if (type === 'unit') newSettings.unitsOfMeasure.splice(index, 1);
    onUpdateSettings(newSettings);
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-gray-100 min-h-[500px] flex">
      {/* Sidebar de Configuración */}
      <div className="w-64 border-r border-gray-100 bg-gray-50 p-4 space-y-2">
        <button onClick={() => setActiveTab('manufacturers')} className={`w-full text-left px-4 py-2 rounded-lg text-sm font-medium ${activeTab === 'manufacturers' ? 'bg-blue-600 text-white' : 'text-gray-600 hover:bg-gray-200'}`}>Fabricantes</button>
        <button onClick={() => setActiveTab('categories')} className={`w-full text-left px-4 py-2 rounded-lg text-sm font-medium ${activeTab === 'categories' ? 'bg-blue-600 text-white' : 'text-gray-600 hover:bg-gray-200'}`}>Categorías</button>
        <button onClick={() => setActiveTab('units')} className={`w-full text-left px-4 py-2 rounded-lg text-sm font-medium ${activeTab === 'units' ? 'bg-blue-600 text-white' : 'text-gray-600 hover:bg-gray-200'}`}>Unidades de Medida</button>
        {isEditable && (
          <button onClick={() => setActiveTab('roles')} className={`w-full text-left px-4 py-2 rounded-lg text-sm font-medium ${activeTab === 'roles' ? 'bg-blue-600 text-white' : 'text-gray-600 hover:bg-gray-200'}`}>Permisos de Roles</button>
        )}
      </div>

      {/* Contenido Principal */}
      <div className="flex-1 p-8">
        {activeTab === 'manufacturers' && (
          <div className="space-y-6">
            <h2 className="text-xl font-bold">Gestión de Fabricantes</h2>
            {isEditable && (
              <div className="flex gap-2">
                <input value={newItem.code} onChange={e => setNewItem({...newItem, code: e.target.value})} placeholder="Código" className="border p-2 rounded w-24 uppercase" />
                <input value={newItem.name} onChange={e => setNewItem({...newItem, name: e.target.value})} placeholder="Nombre" className="border p-2 rounded flex-1 uppercase" />
                <button onClick={() => addItem('manufacturer')} className="bg-blue-600 text-white px-4 py-2 rounded">+</button>
              </div>
            )}
            <div className="border rounded-lg overflow-hidden">
              <table className="w-full text-sm">
                <thead className="bg-gray-50"><tr><th className="p-3 text-left">Código</th><th className="p-3 text-left">Nombre</th><th className="p-3"></th></tr></thead>
                <tbody className="divide-y">
                  {settings.manufacturers.map((m, i) => (
                    <tr key={m.code}>
                      <td className="p-3 font-mono font-bold">{m.code}</td>
                      <td className="p-3">{m.name}</td>
                      <td className="p-3 text-right">
                        {isEditable && <button onClick={() => removeItem('manufacturer', i)} className="text-red-500 hover:bg-red-50 p-1 rounded">Eliminar</button>}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'categories' && (
          <div className="space-y-6">
            <h2 className="text-xl font-bold">Gestión de Categorías</h2>
            {isEditable && (
              <div className="flex gap-2">
                <input value={newItem.code} onChange={e => setNewItem({...newItem, code: e.target.value})} placeholder="Código" className="border p-2 rounded w-32 uppercase" />
                <input value={newItem.desc} onChange={e => setNewItem({...newItem, desc: e.target.value})} placeholder="Descripción" className="border p-2 rounded flex-1 uppercase" />
                <button onClick={() => addItem('category')} className="bg-blue-600 text-white px-4 py-2 rounded">+</button>
              </div>
            )}
            <div className="border rounded-lg overflow-hidden">
              <table className="w-full text-sm">
                <thead className="bg-gray-50"><tr><th className="p-3 text-left">Código</th><th className="p-3 text-left">Descripción</th><th className="p-3"></th></tr></thead>
                <tbody className="divide-y">
                  {settings.categories.map((c, i) => (
                    <tr key={c.code}>
                      <td className="p-3 font-mono font-bold">{c.code}</td>
                      <td className="p-3">{c.description}</td>
                      <td className="p-3 text-right">
                        {isEditable && <button onClick={() => removeItem('category', i)} className="text-red-500 hover:bg-red-50 p-1 rounded">Eliminar</button>}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'units' && (
          <div className="space-y-6">
            <h2 className="text-xl font-bold">Unidades de Medida</h2>
            {isEditable && (
              <div className="flex gap-2">
                <input value={newItem.unit} onChange={e => setNewItem({...newItem, unit: e.target.value})} placeholder="Nueva Unidad (Ej: METRO)" className="border p-2 rounded flex-1 uppercase" />
                <button onClick={() => addItem('unit')} className="bg-blue-600 text-white px-4 py-2 rounded">+</button>
              </div>
            )}
            <div className="flex flex-wrap gap-2">
              {settings.unitsOfMeasure.map((u, i) => (
                <div key={u} className="flex items-center bg-gray-100 px-3 py-1 rounded-full border">
                  <span className="text-sm font-medium">{u}</span>
                  {isEditable && <button onClick={() => removeItem('unit', i)} className="ml-2 text-gray-400 hover:text-red-500">×</button>}
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'roles' && isEditable && (
          <div className="space-y-6">
            <h2 className="text-xl font-bold">Permisos por Perfil</h2>
            <div className="space-y-8">
              {[UserRole.TECNICO, UserRole.COMPRAS].map(role => (
                <div key={role} className="border p-6 rounded-xl bg-gray-50">
                  <h3 className="text-lg font-bold text-blue-800 mb-4">{role}</h3>
                  <div className="space-y-4">
                    <label className="flex items-center gap-3 p-3 bg-white border rounded-lg cursor-pointer hover:bg-blue-50">
                      <input 
                        type="checkbox" 
                        className="w-5 h-5"
                        checked={settings.permissions[role].canCreateProduct}
                        onChange={() => handleTogglePermission(role, 'canCreateProduct')}
                      />
                      <div>
                        <span className="block font-bold">Creación de Productos</span>
                        <span className="text-xs text-gray-500">Permite usar el botón "+" y el formulario de alta.</span>
                      </div>
                    </label>
                    <label className="flex items-center gap-3 p-3 bg-white border rounded-lg cursor-pointer hover:bg-blue-50">
                      <input 
                        type="checkbox" 
                        className="w-5 h-5"
                        checked={settings.permissions[role].canManageMasterData}
                        onChange={() => handleTogglePermission(role, 'canManageMasterData')}
                      />
                      <div>
                        <span className="block font-bold">Gestión de Datos Maestros</span>
                        <span className="text-xs text-gray-500">Permite entrar a esta sección y ver listas maestras.</span>
                      </div>
                    </label>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Settings;

import React, { useState, useEffect } from 'react';
import { 
  ProductType, 
  CostingMethod, 
  Product,
  Manufacturer,
  ItemCategory
} from '../types';

interface ProductFormProps {
  onSave: (product: Product) => void;
  onCancel: () => void;
  existingProducts: Product[];
  manufacturers: Manufacturer[];
  categories: ItemCategory[];
  units: string[];
}

const ProductForm: React.FC<ProductFormProps> = ({ 
  onSave, 
  onCancel, 
  existingProducts,
  manufacturers,
  categories,
  units
}) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState<Partial<Product>>({
    type: ProductType.FABRICANTE,
    baseUnitOfMeasure: units[0] || 'UD',
    inventoryPostingGroup: 'MERCADERÍA', 
    genProdPostingGroup: 'MERCADERÍA',
    vatProdPostingGroup: 'IVA21',        
    costingMethod: CostingMethod.FIFO,
    unitPrice: 0,
    unitCost: 0,
    dimensionCode: 'GASTOS',            
    dimensionValueCode: 'MATERIAL',
    valuePosting: 'Mismo código',
    description: ''
  });

  const [manufacturerRef, setManufacturerRef] = useState('');
  const [descriptionTouched, setDescriptionTouched] = useState(false);

  useEffect(() => {
    let prefix = '';
    if (formData.type === ProductType.FABRICANTE && formData.manufacturerCode) {
      prefix = formData.manufacturerCode.substring(0, 3).toUpperCase();
    } else if (formData.type === ProductType.GENERICO && formData.itemCategoryCode) {
      prefix = `G${formData.itemCategoryCode.substring(0, 3).toUpperCase()}`;
    }

    if (prefix) {
      const matching = existingProducts.filter(p => p.no.startsWith(prefix));
      let nextNumber = 1;
      if (matching.length > 0) {
        const numbers = matching.map(p => {
          const numPart = p.no.substring(prefix.length);
          return parseInt(numPart, 10) || 0;
        });
        nextNumber = Math.max(...numbers) + 1;
      }
      const formattedNumber = nextNumber.toString().padStart(4, '0');
      setFormData(prev => ({ ...prev, no: `${prefix}${formattedNumber}` }));
    } else {
      setFormData(prev => ({ ...prev, no: '' }));
    }
  }, [formData.type, formData.manufacturerCode, formData.itemCategoryCode, existingProducts]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    let processedValue: any = value;
    if (name === 'description') processedValue = value.toUpperCase();
    if (name === 'unitPrice' || name === 'unitCost') processedValue = parseFloat(value) || 0;
    setFormData(prev => ({ ...prev, [name]: processedValue }));
  };

  const validateAndSave = () => {
    const desc = formData.description?.trim();
    if (!desc) return;
    let finalDescription = desc;
    if (formData.type === ProductType.FABRICANTE && manufacturerRef) {
        const refSuffix = ` REF. ${manufacturerRef}`;
        if (!finalDescription.endsWith(refSuffix)) finalDescription = `${finalDescription}${refSuffix}`;
    }
    const completeProduct: Product = {
      ...formData as Product,
      description: finalDescription,
      manufacturerRef: manufacturerRef,
      inventoryPostingGroup: 'MERCADERÍA',
      vatProdPostingGroup: 'IVA21',
      dimensionCode: 'GASTOS'
    };
    onSave(completeProduct);
  };

  const isDescriptionValid = formData.description && formData.description.trim().length > 0;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between mb-8 px-4">
        {[1, 2, 3].map((s) => (
          <div key={s} className="flex items-center">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold ${step === s ? 'bg-blue-600 text-white' : step > s ? 'bg-green-500 text-white' : 'bg-gray-200 text-gray-600'}`}>
              {s}
            </div>
            {s < 3 && <div className={`h-1 w-12 mx-2 ${step > s ? 'bg-green-500' : 'bg-gray-200'}`} />}
          </div>
        ))}
      </div>

      {step === 1 && (
        <div className="space-y-4">
          <h4 className="text-lg font-medium text-gray-700 text-center">Seleccione Tipo de Producto</h4>
          <div className="grid grid-cols-2 gap-4">
            <button
              onClick={() => { setFormData({ ...formData, type: ProductType.FABRICANTE }); setStep(2); }}
              className={`p-6 border-2 rounded-xl text-left transition-all ${formData.type === ProductType.FABRICANTE ? 'border-blue-600 bg-blue-50' : 'border-gray-200 hover:border-blue-300'}`}
            >
              <div className="text-xl font-bold text-blue-700">Fabricante</div>
              <p className="text-sm text-gray-500 mt-1">Requiere referencia externa.</p>
            </button>
            <button
              onClick={() => { setFormData({ ...formData, type: ProductType.GENERICO }); setStep(2); }}
              className={`p-6 border-2 rounded-xl text-left transition-all ${formData.type === ProductType.GENERICO ? 'border-blue-600 bg-blue-50' : 'border-gray-200 hover:border-blue-300'}`}
            >
              <div className="text-xl font-bold text-blue-700">Genérico</div>
              <p className="text-sm text-gray-500 mt-1">Categoría general estándar.</p>
            </button>
          </div>
        </div>
      )}

      {step === 2 && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Fabricante (Tabla 5720)</label>
            <select
              name="manufacturerCode"
              value={formData.manufacturerCode || ''}
              onChange={handleInputChange}
              className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
              disabled={formData.type === ProductType.GENERICO}
            >
              <option value="">Seleccione fabricante...</option>
              {manufacturers.map(m => <option key={m.code} value={m.code}>{m.code} - {m.name}</option>)}
            </select>
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Categoría (Tabla 5722)</label>
            <select
              name="itemCategoryCode"
              value={formData.itemCategoryCode || ''}
              onChange={handleInputChange}
              className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
            >
              <option value="">Seleccione categoría...</option>
              {categories.map(c => <option key={c.code} value={c.code}>{c.code} - {c.description}</option>)}
            </select>
          </div>

          {formData.type === ProductType.FABRICANTE && (
            <div className="space-y-2 col-span-full">
              <label className="block text-sm font-semibold text-gray-600">Nro. de Referencia del Fabricante *</label>
              <input
                type="text"
                value={manufacturerRef}
                onChange={(e) => setManufacturerRef(e.target.value.toUpperCase())}
                placeholder="Ej: REF-12345"
                className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                required
              />
            </div>
          )}

          <div className="space-y-2 col-span-full">
            <label className="block text-sm font-semibold text-gray-600">No. (Código Correlativo Autogenerado)</label>
            <input
              type="text"
              readOnly
              value={formData.no || ''}
              className="w-full p-3 border border-blue-200 bg-blue-50 rounded text-blue-800 font-mono font-bold"
            />
          </div>

          <div className="flex justify-between col-span-full mt-4">
            <button onClick={() => setStep(1)} className="px-6 py-2 border border-gray-300 rounded text-gray-600 hover:bg-gray-50">Atrás</button>
            <button 
              onClick={() => setStep(3)} 
              disabled={!formData.no || (formData.type === ProductType.FABRICANTE && !manufacturerRef)}
              className="px-6 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50"
            >
              Siguiente
            </button>
          </div>
        </div>
      )}

      {step === 3 && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2 col-span-full">
            <label className="block text-sm font-semibold text-gray-600">Descripción (MAYÚSCULAS) *</label>
            <input
              type="text"
              name="description"
              maxLength={100}
              value={formData.description || ''}
              onBlur={() => setDescriptionTouched(true)}
              onChange={handleInputChange}
              placeholder="DESCRIPCIÓN"
              className={`w-full p-2 border rounded focus:ring-2 focus:ring-blue-500 outline-none uppercase ${descriptionTouched && !isDescriptionValid ? 'border-red-500 bg-red-50' : 'border-gray-300'}`}
              required
            />
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Unidad medida base</label>
            <select name="baseUnitOfMeasure" value={formData.baseUnitOfMeasure} onChange={handleInputChange} className="w-full p-2 border border-gray-300 rounded">
              {units.map(u => <option key={u} value={u}>{u}</option>)}
            </select>
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Precio venta</label>
            <input type="number" name="unitPrice" value={formData.unitPrice} onChange={handleInputChange} className="w-full p-2 border border-gray-300 rounded" />
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Coste unitario</label>
            <input type="number" name="unitCost" value={formData.unitCost} onChange={handleInputChange} className="w-full p-2 border border-gray-300 rounded" />
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Valoración existencias</label>
            <select name="costingMethod" value={formData.costingMethod} onChange={handleInputChange} className="w-full p-2 border border-gray-300 rounded">
              {Object.values(CostingMethod).map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>

          <div className="col-span-full bg-blue-50 p-4 rounded-lg border border-blue-100 mt-4 text-xs">
            <div className="grid grid-cols-3 gap-2 text-center">
              <div><span className="text-blue-400">Dimensión:</span><br/><strong>GASTOS</strong></div>
              <div><span className="text-blue-400">Inventario:</span><br/><strong>MERCADERÍA</strong></div>
              <div><span className="text-blue-400">IVA:</span><br/><strong>IVA21</strong></div>
            </div>
          </div>

          <div className="flex justify-between col-span-full mt-6 border-t pt-4">
            <button onClick={() => setStep(2)} className="px-6 py-2 border border-gray-300 rounded text-gray-600 hover:bg-gray-50">Atrás</button>
            <div className="space-x-4">
                <button onClick={onCancel} className="px-6 py-2 text-red-600 hover:bg-red-50 rounded">Cancelar</button>
                <button 
                  onClick={validateAndSave} 
                  disabled={!isDescriptionValid}
                  className="px-8 py-2 bg-blue-600 text-white font-bold rounded shadow-lg hover:bg-blue-700 disabled:opacity-50"
                >
                  Crear Producto
                </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProductForm;

import React, { useState, useEffect } from 'react';
import { Product, UserRole, AppSettings, RolePermissions } from './types';
import Modal from './components/Modal';
import ProductForm from './components/ProductForm';
import Settings from './components/Settings';
import { ITEM_CATEGORIES, MANUFACTURERS, UNITS_OF_MEASURE } from './constants';

const DEFAULT_SETTINGS: AppSettings = {
  manufacturers: MANUFACTURERS,
  categories: ITEM_CATEGORIES,
  unitsOfMeasure: UNITS_OF_MEASURE,
  permissions: {
    [UserRole.ADMIN]: { canCreateProduct: true, canManageMasterData: true },
    [UserRole.TECNICO]: { canCreateProduct: true, canManageMasterData: false },
    [UserRole.COMPRAS]: { canCreateProduct: false, canManageMasterData: false },
  }
};

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'products' | 'settings'>('products');
  const [currentUser, setCurrentUser] = useState<UserRole>(UserRole.ADMIN);
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('bc_products');
    return saved ? JSON.parse(saved) : [];
  });
