import React, { useRef, useState } from 'react';
import { ExternalProduct } from '../types';

interface ExternalProductsProps {
  externalProducts: ExternalProduct[];
  onUpload: (products: ExternalProduct[]) => void;
  onClear: () => void;
}

const ExternalProducts: React.FC<ExternalProductsProps> = ({ externalProducts, onUpload, onClear }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const processFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const data = e.target?.result;
      const workbook = (window as any).XLSX.read(data, { type: 'binary' });
      const firstSheetName = workbook.SheetNames[0];
      const worksheet = workbook.Sheets[firstSheetName];
      const json = (window as any).XLSX.utils.sheet_to_json(worksheet);

      const mapped: ExternalProduct[] = json.map((row: any) => ({
        no: String(row['Nº'] || row['No.'] || row['nº'] || row['no'] || '').trim(),
        description: String(row['Descripción'] || row['Descripcion'] || row['description'] || '').trim()
      })).filter((p: any) => p.no && p.description);

      onUpload(mapped);
    };
    reader.readAsBinaryString(file);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      processFile(e.target.files[0]);
    }
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const onDragLeave = () => setIsDragging(false);

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-gray-800">Maestro Externo (Business Central)</h2>
          <p className="text-sm text-gray-500">Cargue el listado actual de BC para sincronizar los números correlativos.</p>
        </div>
        {externalProducts.length > 0 && (
          <button 
            onClick={onClear}
            className="text-red-600 hover:text-red-800 text-sm font-bold bg-red-50 px-4 py-2 rounded-lg border border-red-100"
          >
            Limpiar Maestro Externo
          </button>
        )}
      </div>

      <div 
        onDragOver={onDragOver}
        onDragLeave={onDragLeave}
        onDrop={onDrop}
        onClick={() => fileInputRef.current?.click()}
        className={`border-2 border-dashed rounded-xl p-10 flex flex-col items-center justify-center cursor-pointer transition-all ${
          isDragging ? 'border-blue-500 bg-blue-50' : 'border-gray-200 bg-white hover:border-blue-300 hover:bg-gray-50'
        }`}
      >
        <input 
          type="file" 
          ref={fileInputRef} 
          onChange={handleFileChange} 
          accept=".xlsx, .xls, .csv" 
          className="hidden" 
        />
        <svg className="w-12 h-12 text-gray-400 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
