      setFormData(prev => ({ ...prev, no: `${prefix}${formattedNumber}` }));
    } else {
      setFormData(prev => ({ ...prev, no: '' }));
    }
  }, [formData.type, formData.manufacturerCode, formData.itemCategoryCode, existingProducts, externalProducts]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    let processedValue: any = value;
    if (name === 'description') processedValue = value.toUpperCase();
    if (name === 'unitPrice' || name === 'unitCost') processedValue = parseFloat(value) || 0;
    setFormData(prev => ({ ...prev, [name]: processedValue }));
  };

  const validateAndSave = () => {
    const desc = formData.description?.trim();
    if (!desc) return;
    let finalDescription = desc;
    if (formData.type === ProductType.FABRICANTE && manufacturerRef) {
        const refSuffix = ` REF. ${manufacturerRef}`;
        if (!finalDescription.endsWith(refSuffix)) finalDescription = `${finalDescription}${refSuffix}`;
    }
    const completeProduct: Product = {
      ...formData as Product,
      description: finalDescription,
      manufacturerRef: manufacturerRef,
      inventoryPostingGroup: 'MERCADERÍA',
      vatProdPostingGroup: 'IVA21',
      dimensionCode: 'GASTOS'
    };
    onSave(completeProduct);
  };

  const isDescriptionValid = formData.description && formData.description.trim().length > 0;
  const isCategoryValid = !!formData.itemCategoryCode;
  const isManufacturerValid = formData.type === ProductType.GENERICO || !!formData.manufacturerCode;
  const isRefValid = formData.type === ProductType.GENERICO || !!manufacturerRef;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between mb-8 px-4">
        {[1, 2, 3].map((s) => (
          <div key={s} className="flex items-center">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold ${step === s ? 'bg-blue-600 text-white' : step > s ? 'bg-green-500 text-white' : 'bg-gray-200 text-gray-600'}`}>
              {s}
            </div>
            {s < 3 && <div className={`h-1 w-12 mx-2 ${step > s ? 'bg-green-500' : 'bg-gray-200'}`} />}
          </div>
        ))}
      </div>

      {step === 1 && (
        <div className="space-y-4">
          <h4 className="text-lg font-medium text-gray-700 text-center">Seleccione Tipo de Producto</h4>
          <div className="grid grid-cols-2 gap-4">
            <button
              onClick={() => { setFormData({ ...formData, type: ProductType.FABRICANTE }); setStep(2); }}
              className={`p-6 border-2 rounded-xl text-left transition-all ${formData.type === ProductType.FABRICANTE ? 'border-blue-600 bg-blue-50' : 'border-gray-200 hover:border-blue-300'}`}
            >
              <div className="text-xl font-bold text-blue-700">Fabricante</div>
              <p className="text-sm text-gray-500 mt-1">Requiere referencia externa.</p>
            </button>
            <button
              onClick={() => { setFormData({ ...formData, type: ProductType.GENERICO }); setStep(2); }}
              className={`p-6 border-2 rounded-xl text-left transition-all ${formData.type === ProductType.GENERICO ? 'border-blue-600 bg-blue-50' : 'border-gray-200 hover:border-blue-300'}`}
            >
              <div className="text-xl font-bold text-blue-700">Genérico</div>
              <p className="text-sm text-gray-500 mt-1">Categoría general estándar.</p>
            </button>
          </div>
        </div>
      )}

      {step === 2 && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Fabricante (Tabla 5720) {formData.type === ProductType.FABRICANTE && <span className="text-red-500">*</span>}</label>
            <select
              name="manufacturerCode"
              value={formData.manufacturerCode || ''}
              onChange={handleInputChange}
              className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
              disabled={formData.type === ProductType.GENERICO}
            >
              <option value="">Seleccione fabricante...</option>
              {manufacturers.map(m => <option key={m.code} value={m.code}>{m.code} - {m.name}</option>)}
            </select>
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Categoría (Tabla 5722) <span className="text-red-500">*</span></label>
            <select
              name="itemCategoryCode"
              value={formData.itemCategoryCode || ''}
              onBlur={() => setCategoryTouched(true)}
              onChange={handleInputChange}
              className={`w-full p-2 border rounded focus:ring-2 focus:ring-blue-500 outline-none ${categoryTouched && !isCategoryValid ? 'border-red-500 bg-red-50' : 'border-gray-300'}`}
              required
            >
              <option value="">Seleccione categoría...</option>
              {categories.map(c => <option key={c.code} value={c.code}>{c.code} - {c.description}</option>)}
            </select>
            {categoryTouched && !isCategoryValid && (
              <p className="text-[10px] text-red-500 font-bold">La selección de categoría es obligatoria.</p>
            )}
          </div>

          {formData.type === ProductType.FABRICANTE && (
            <div className="space-y-2 col-span-full">
              <label className="block text-sm font-semibold text-gray-600">Nro. de Referencia del Fabricante *</label>
              <input
                type="text"
                value={manufacturerRef}
                onChange={(e) => setManufacturerRef(e.target.value.toUpperCase())}
                placeholder="Ej: REF-12345"
                className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
                required
              />
            </div>
          )}

          <div className="space-y-2 col-span-full">
            <label className="block text-sm font-semibold text-gray-600">No. (Código Correlativo Autogenerado)</label>
            <input
              type="text"
              readOnly
              value={formData.no || ''}
              className="w-full p-3 border border-blue-200 bg-blue-50 rounded text-blue-800 font-mono font-bold"
            />
            <p className="text-[10px] text-blue-400 mt-1">Calculado sobre app + maestro externo BC</p>
          </div>

          <div className="flex justify-between col-span-full mt-4">
            <button onClick={() => setStep(1)} className="px-6 py-2 border border-gray-300 rounded text-gray-600 hover:bg-gray-50">Atrás</button>
            <button 
              onClick={() => setStep(3)} 
              disabled={!formData.no || !isCategoryValid || !isManufacturerValid || !isRefValid}
              className="px-6 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50 transition-all"
            >
              Siguiente
            </button>
          </div>
        </div>
      )}

      {step === 3 && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2 col-span-full">
            <label className="block text-sm font-semibold text-gray-600">Descripción (MAYÚSCULAS) *</label>
            <input
              type="text"
              name="description"
              maxLength={100}
              value={formData.description || ''}
              onBlur={() => setDescriptionTouched(true)}
              onChange={handleInputChange}
              placeholder="DESCRIPCIÓN"
              className={`w-full p-2 border rounded focus:ring-2 focus:ring-blue-500 outline-none uppercase ${descriptionTouched && !isDescriptionValid ? 'border-red-500 bg-red-50' : 'border-gray-300'}`}
              required
            />
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Unidad medida base</label>
            <select name="baseUnitOfMeasure" value={formData.baseUnitOfMeasure} onChange={handleInputChange} className="w-full p-2 border border-gray-300 rounded">
              {units.map(u => <option key={u} value={u}>{u}</option>)}
            </select>
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Precio venta</label>
            <input type="number" name="unitPrice" value={formData.unitPrice} onChange={handleInputChange} className="w-full p-2 border border-gray-300 rounded" />
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Coste unitario</label>
            <input type="number" name="unitCost" value={formData.unitCost} onChange={handleInputChange} className="w-full p-2 border border-gray-300 rounded" />
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Valoración existencias</label>
            <select name="costingMethod" value={formData.costingMethod} onChange={handleInputChange} className="w-full p-2 border border-gray-300 rounded">
              {Object.values(CostingMethod).map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>

          <div className="col-span-full bg-blue-50 p-4 rounded-lg border border-blue-100 mt-4 text-xs">
            <div className="grid grid-cols-3 gap-2 text-center">
              <div><span className="text-blue-400">Dimensión:</span><br/><strong>GASTOS</strong></div>
              <div><span className="text-blue-400">Inventario:</span><br/><strong>MERCADERÍA</strong></div>
              <div><span className="text-blue-400">IVA:</span><br/><strong>IVA21</strong></div>
            </div>
          </div>

          <div className="flex justify-between col-span-full mt-6 border-t pt-4">
            <button onClick={() => setStep(2)} className="px-6 py-2 border border-gray-300 rounded text-gray-600 hover:bg-gray-50">Atrás</button>
            <div className="space-x-4">
                <button onClick={onCancel} className="px-6 py-2 text-red-600 hover:bg-red-50 rounded">Cancelar</button>
                <button 
                  onClick={validateAndSave} 
                  disabled={!isDescriptionValid}
                  className="px-8 py-2 bg-blue-600 text-white font-bold rounded shadow-lg hover:bg-blue-700 disabled:opacity-50"
                >
                  Crear Producto
                </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProductForm;

import React, { useState, useEffect } from 'react';
import { Product, UserRole, AppSettings, ExternalProduct } from './types';
import Modal from './components/Modal';
import ProductForm from './components/ProductForm';
import Settings from './components/Settings';
import ExternalProducts from './components/ExternalProducts';
import { ITEM_CATEGORIES, MANUFACTURERS, UNITS_OF_MEASURE } from './constants';

const DEFAULT_SETTINGS: AppSettings = {
  manufacturers: MANUFACTURERS,
  categories: ITEM_CATEGORIES,
  unitsOfMeasure: UNITS_OF_MEASURE,
  permissions: {
    [UserRole.ADMIN]: { canCreateProduct: true, canManageMasterData: true },
    [UserRole.TECNICO]: { canCreateProduct: true, canManageMasterData: false },
    [UserRole.COMPRAS]: { canCreateProduct: false, canManageMasterData: false },
  }
};

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'products' | 'bc' | 'settings'>('products');
  const [currentUser, setCurrentUser] = useState<UserRole>(UserRole.ADMIN);
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('bc_products');
    return saved ? JSON.parse(saved) : [];
  });
  const [externalProducts, setExternalProducts] = useState<ExternalProduct[]>(() => {
    const saved = localStorage.getItem('bc_external_products');
    return saved ? JSON.parse(saved) : [];
  });
  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem('bc_settings');
    return saved ? JSON.parse(saved) : DEFAULT_SETTINGS;
  });
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    localStorage.setItem('bc_products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('bc_external_products', JSON.stringify(externalProducts));
  }, [externalProducts]);

  useEffect(() => {
    localStorage.setItem('bc_settings', JSON.stringify(settings));
  }, [settings]);

  const userPerms = settings.permissions[currentUser];

  const handleAddProduct = (newProduct: Product) => {
    setProducts(prev => [newProduct, ...prev]);
    setIsModalOpen(false);
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-20">
      <div className="bg-gray-800 text-white text-[10px] py-1 px-4 flex justify-between items-center uppercase tracking-widest font-bold">
        <span>SISTEMA DE GESTIÓN DE PRODUCTOS BC</span>
        <div className="flex items-center gap-3">
          <span>PERFIL ACTUAL:</span>
          <select 
            value={currentUser} 
            onChange={(e) => {
              const role = e.target.value as UserRole;
              setCurrentUser(role);
              if (!settings.permissions[role].canManageMasterData && activeView === 'settings') setActiveView('products');
            }}
            className="bg-gray-700 text-white border-none text-[10px] rounded focus:ring-0"
          >
            {Object.values(UserRole).map(role => <option key={role} value={role}>{role}</option>)}
          </select>
        </div>
      </div>

      <header className="bg-white border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div>
              <h1 className="text-xl font-black text-green-600 leading-none">TECMELEC</h1>
              <span className="text-xs text-gray-400 font-bold uppercase">Alta de productos</span>
            </div>

            <nav className="flex gap-1 bg-gray-100 p-1 rounded-lg">
              <button 
                onClick={() => setActiveView('products')}
                className={`px-4 py-2 rounded-md text-sm font-bold transition-all ${activeView === 'products' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                Productos
              </button>
              <button 
                onClick={() => setActiveView('bc')}
                className={`px-4 py-2 rounded-md text-sm font-bold transition-all ${activeView === 'bc' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                Productos BC
              </button>
              {userPerms.canManageMasterData && (
                <button 
                  onClick={() => setActiveView('settings')}
                  className={`px-4 py-2 rounded-md text-sm font-bold transition-all ${activeView === 'settings' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                  Configuración
                </button>
              )}
            </nav>
          </div>

          {activeView === 'products' && userPerms.canCreateProduct && (
            <button
              onClick={() => setIsModalOpen(true)}
              className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-lg font-bold shadow-lg shadow-blue-200 flex items-center gap-2 transform active:scale-95 transition-all"
            >
              <span className="text-lg">+</span> Nuevo producto
            </button>
          )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 md:p-8">
        {activeView === 'products' && (
          <div className="space-y-6">
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead className="bg-gray-50 border-b border-gray-100">
                    <tr>
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-wider">No.</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-wider">Descripción</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-wider">Tipo</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-wider">Precio</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-wider">Fabricante</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-wider">U.M.</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {products.length === 0 ? (
                      <tr>
                        <td colSpan={6} className="px-6 py-20 text-center text-gray-400">
                          <p>No hay productos registrados.</p>
                        </td>
                      </tr>
                    ) : (
                      products.map((p, idx) => (
                        <tr key={idx} className="hover:bg-blue-50/30 transition-colors">
                          <td className="px-6 py-4 font-mono text-sm text-blue-700 font-bold">{p.no}</td>
                          <td className="px-6 py-4 text-sm text-gray-800 uppercase font-medium">{p.description}</td>
                          <td className="px-6 py-4">
                            <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase ${p.type === 'Fabricante' ? 'bg-indigo-100 text-indigo-700' : 'bg-green-100 text-green-700'}`}>
                              {p.type}
                            </span>
                          </td>
                          <td className="px-6 py-4 text-sm text-gray-900 font-semibold">{p.unitPrice.toLocaleString('es-ES', { style: 'currency', currency: 'EUR' })}</td>
                          <td className="px-6 py-4 text-sm text-gray-500 font-bold">{p.manufacturerCode || '-'}</td>
                          <td className="px-6 py-4 text-sm text-gray-500">{p.baseUnitOfMeasure}</td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeView === 'bc' && (
          <ExternalProducts 
            externalProducts={externalProducts} 
            onUpload={setExternalProducts}
            onClear={() => setExternalProducts([])}
          />
        )}

        {activeView === 'settings' && (
          <Settings 
            settings={settings} 
            onUpdateSettings={setSettings} 
            currentRole={currentUser}
          />
        )}
      </main>

      <Modal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        title="Alta de Producto"
      >
        <ProductForm 
          onSave={handleAddProduct}
          onCancel={() => setIsModalOpen(false)}
          existingProducts={products}
          externalProducts={externalProducts}
          manufacturers={settings.manufacturers}
          categories={settings.categories}
          units={settings.unitsOfMeasure}
        />
      </Modal>
    </div>
  );
};

export default App;

import React, { useRef, useState } from 'react';
import { ExternalProduct, Manufacturer, ItemCategory } from '../types';

interface ExternalProductsProps {
  externalProducts: ExternalProduct[];
  onUploadProducts: (products: ExternalProduct[]) => void;
  onUploadManufacturers: (manufacturers: Manufacturer[]) => void;
  onUploadCategories: (categories: ItemCategory[]) => void;
  onClearProducts: () => void;
  isAdmin: boolean;
}

const ExternalProducts: React.FC<ExternalProductsProps> = ({ 
  externalProducts, 
  onUploadProducts, 
  onUploadManufacturers,
  onUploadCategories,
  onClearProducts,
  isAdmin 
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const mfgInputRef = useRef<HTMLInputElement>(null);
  const catInputRef = useRef<HTMLInputElement>(null);

  const [isDragging, setIsDragging] = useState<string | null>(null);

  const processFile = (file: File, type: 'products' | 'manufacturers' | 'categories') => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const data = e.target?.result;
      const workbook = (window as any).XLSX.read(data, { type: 'binary' });
      const firstSheetName = workbook.SheetNames[0];
      const worksheet = workbook.Sheets[firstSheetName];
      const json = (window as any).XLSX.utils.sheet_to_json(worksheet);

      if (type === 'products') {
        const mapped: ExternalProduct[] = json.map((row: any) => ({
          no: String(row['Nº'] || row['No.'] || row['nº'] || row['no'] || '').trim(),
          description: String(row['Descripción'] || row['Descripcion'] || row['description'] || '').trim()
        })).filter((p: any) => p.no && p.description);
        onUploadProducts(mapped);
      } else if (type === 'manufacturers') {
        const mapped: Manufacturer[] = json.map((row: any) => ({
          code: String(row['Código'] || row['Codigo'] || row['code'] || '').trim().toUpperCase(),
          name: String(row['Nombre'] || row['name'] || '').trim().toUpperCase()
        })).filter((m: any) => m.code && m.name);
        onUploadManufacturers(mapped);
      } else if (type === 'categories') {
        const mapped: ItemCategory[] = json.map((row: any) => ({
          code: String(row['Código'] || row['Codigo'] || row['code'] || '').trim().toUpperCase(),
          description: String(row['Descripción'] || row['Descripcion'] || row['description'] || '').trim().toUpperCase()
        })).filter((c: any) => c.code && c.description);
        onUploadCategories(mapped);
      }
    };
    reader.readAsBinaryString(file);
  };

  const UploadCard = ({ 
    title, 
    desc, 
    type, 
    inputRef, 
    columns 
  }: { 
    title: string, 
    desc: string, 
    type: 'products' | 'manufacturers' | 'categories', 
    inputRef: React.RefObject<HTMLInputElement>,
    columns: string 
  }) => (
    <div 
      onDragOver={(e) => { e.preventDefault(); setIsDragging(type); }}
      onDragLeave={() => setIsDragging(null)}
      onDrop={(e) => {
        e.preventDefault();
        setIsDragging(null);
        if (e.dataTransfer.files && e.dataTransfer.files[0]) processFile(e.dataTransfer.files[0], type);
      }}
      onClick={() => inputRef.current?.click()}
      className={`border-2 border-dashed rounded-xl p-6 flex flex-col items-center justify-center cursor-pointer transition-all ${
        isDragging === type ? 'border-blue-500 bg-blue-50' : 'border-gray-200 bg-white hover:border-blue-300 hover:bg-gray-50'
      }`}
    >
      <input 
        type="file" 
        ref={inputRef} 
        onChange={(e) => e.target.files?.[0] && processFile(e.target.files[0], type)} 
        accept=".xlsx, .xls, .csv" 
        className="hidden" 
      />
      <svg className={`w-8 h-8 mb-2 ${isDragging === type ? 'text-blue-500' : 'text-gray-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
      </svg>
      <h3 className="font-bold text-gray-700 text-sm">{title}</h3>
      <p className="text-[11px] text-gray-500 text-center mt-1">{desc}</p>
      <p className="text-[10px] text-blue-500 font-mono mt-2 bg-blue-50 px-2 py-0.5 rounded border border-blue-100 uppercase">{columns}</p>
    </div>
  );

  return (
    <div className="space-y-8">
      {/* Sección Maestro Externo BC (Siempre visible) */}
      <div className="space-y-4">
        <div className="flex justify-between items-center">
          <div>
            <h2 className="text-xl font-bold text-gray-800">Maestro Externo (Business Central)</h2>
            <p className="text-sm text-gray-500">Sincronización de números correlativos.</p>
          </div>
          {externalProducts.length > 0 && (
            <button 
              onClick={onClearProducts}
              className="text-red-600 hover:text-red-800 text-xs font-bold bg-red-50 px-3 py-1.5 rounded-lg border border-red-100"
            >
              Limpiar Maestro
            </button>
          )}
        </div>
        <UploadCard 
          title="Carga de Productos BC" 
          desc="Arrastra el excel con los productos actuales de BC" 
          type="products" 
          inputRef={fileInputRef}
          columns="Nº, Descripción"
        />
      </div>

      {/* Secciones de Datos Maestros (Solo Administrador) */}
      {isAdmin && (
        <div className="pt-6 border-t border-gray-200">
          <div className="mb-4">
            <h2 className="text-xl font-bold text-green-700">Gestión Masiva de Datos Maestros</h2>
            <p className="text-sm text-gray-500">Solo visible para el perfil Administrador.</p>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <UploadCard 
              title="Importar Fabricantes" 
              desc="Actualiza la Tabla 5720 de BC" 
              type="manufacturers" 
              inputRef={mfgInputRef}
              columns="Código, Nombre"
            />
            <UploadCard 
              title="Importar Categorías" 
              desc="Actualiza la Tabla 5722 de BC" 
              type="categories" 
              inputRef={catInputRef}
              columns="Código, Descripción"
            />
          </div>
        </div>
      )}

      {/* Listado de Productos Cargados */}
      {externalProducts.length > 0 && (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
          <div className="bg-gray-50 px-6 py-3 border-b border-gray-100 flex justify-between items-center">
            <span className="text-xs font-bold text-gray-500 uppercase">Registros Importados</span>
            <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2 py-1 rounded-full">{externalProducts.length} productos</span>
          </div>
          <div className="max-h-72 overflow-y-auto overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead className="bg-gray-50 sticky top-0">
                <tr>
                  <th className="px-6 py-3 font-bold text-gray-500">Nº</th>
                  <th className="px-6 py-3 font-bold text-gray-500">Descripción</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {externalProducts.map((p, i) => (
                  <tr key={i} className="hover:bg-gray-50">
                    <td className="px-6 py-3 font-mono text-blue-600 font-bold">{p.no}</td>
                    <td className="px-6 py-3 text-gray-700 uppercase">{p.description}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default ExternalProducts;

import React, { useState, useEffect } from 'react';
import { Product, UserRole, AppSettings, ExternalProduct, Manufacturer, ItemCategory } from './types';
import Modal from './components/Modal';
import ProductForm from './components/ProductForm';
import Settings from './components/Settings';
import ExternalProducts from './components/ExternalProducts';
import { ITEM_CATEGORIES, MANUFACTURERS, UNITS_OF_MEASURE } from './constants';

const DEFAULT_SETTINGS: AppSettings = {
  manufacturers: MANUFACTURERS,
  categories: ITEM_CATEGORIES,
  unitsOfMeasure: UNITS_OF_MEASURE,
  permissions: {
    [UserRole.ADMIN]: { canCreateProduct: true, canManageMasterData: true },
    [UserRole.TECNICO]: { canCreateProduct: true, canManageMasterData: false },
    [UserRole.COMPRAS]: { canCreateProduct: false, canManageMasterData: false },
  }
};

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'products' | 'bc' | 'settings'>('products');
  const [currentUser, setCurrentUser] = useState<UserRole>(UserRole.ADMIN);
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('bc_products');
    return saved ? JSON.parse(saved) : [];
  });
  const [externalProducts, setExternalProducts] = useState<ExternalProduct[]>(() => {
    const saved = localStorage.getItem('bc_external_products');
    return saved ? JSON.parse(saved) : [];
  });
  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem('bc_settings');
    return saved ? JSON.parse(saved) : DEFAULT_SETTINGS;
  });
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    localStorage.setItem('bc_products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('bc_external_products', JSON.stringify(externalProducts));
  }, [externalProducts]);

  useEffect(() => {
    localStorage.setItem('bc_settings', JSON.stringify(settings));
  }, [settings]);

  const userPerms = settings.permissions[currentUser];

  const handleAddProduct = (newProduct: Product) => {
    setProducts(prev => [newProduct, ...prev]);
    setIsModalOpen(false);
  };

  const handleBulkManufacturers = (newManufacturers: Manufacturer[]) => {
    setSettings(prev => ({
      ...prev,
      manufacturers: newManufacturers
    }));
    alert(`${newManufacturers.length} fabricantes cargados correctamente.`);
  };

  const handleBulkCategories = (newCategories: ItemCategory[]) => {
    setSettings(prev => ({
      ...prev,
      categories: newCategories
    }));
    alert(`${newCategories.length} categorías cargadas correctamente.`);
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-20">
      <div className="bg-gray-800 text-white text-[10px] py-1 px-4 flex justify-between items-center uppercase tracking-widest font-bold">
        <span>SISTEMA DE GESTIÓN DE PRODUCTOS BC</span>
        <div className="flex items-center gap-3">
          <span>PERFIL ACTUAL:</span>
          <select 
            value={currentUser} 
            onChange={(e) => {
              const role = e.target.value as UserRole;
              setCurrentUser(role);
              if (!settings.permissions[role].canManageMasterData && activeView === 'settings') setActiveView('products');
            }}
            className="bg-gray-700 text-white border-none text-[10px] rounded focus:ring-0"
          >
            {Object.values(UserRole).map(role => <option key={role} value={role}>{role}</option>)}
          </select>
        </div>
      </div>

      <header className="bg-white border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div>
              <h1 className="text-xl font-black text-green-600 leading-none">TECMELEC</h1>
              <span className="text-xs text-gray-400 font-bold uppercase">Alta de productos</span>
            </div>

            <nav className="flex gap-1 bg-gray-100 p-1 rounded-lg">
              <button 
                onClick={() => setActiveView('products')}
                className={`px-4 py-2 rounded-md text-sm font-bold transition-all ${activeView === 'products' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                Productos
              </button>
              <button 
                onClick={() => setActiveView('bc')}
                className={`px-4 py-2 rounded-md text-sm font-bold transition-all ${activeView === 'bc' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                Productos BC
              </button>
              {userPerms.canManageMasterData && (
                <button 
                  onClick={() => setActiveView('settings')}
                  className={`px-4 py-2 rounded-md text-sm font-bold transition-all ${activeView === 'settings' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                  Configuración
                </button>
              )}
            </nav>
          </div>

          {activeView === 'products' && userPerms.canCreateProduct && (
            <button
              onClick={() => setIsModalOpen(true)}
              className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-lg font-bold shadow-lg shadow-blue-200 flex items-center gap-2 transform active:scale-95 transition-all"
            >
              <span className="text-lg">+</span> Nuevo producto
            </button>
          )}
