  const handleSuggestDescription = async () => {
    if (!manufacturerRef) return;

    setIsSuggesting(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Identifica este producto industrial por su referencia y proporciona una descripción técnica corta y profesional en español para un catálogo. Referencia: "${manufacturerRef}". Devuelve SOLO la descripción, sin introducciones ni puntos finales innecesarios.`,
      });

      const suggestedText = response.text?.trim().toUpperCase();
      if (suggestedText) {
        setFormData(prev => ({ ...prev, description: suggestedText }));
      }
    } catch (error) {
      console.error("Error suggesting description:", error);
      alert("No se pudo obtener una sugerencia. Verifique la referencia o su conexión.");
    } finally {
      setIsSuggesting(false);
    }
  };

  const validateAndSave = () => {
