                  title="Sugerir descripción usando IA"
                >
                  {isSuggesting ? (
                    <div className="w-4 h-4 border-2 border-blue-700 border-t-transparent rounded-full animate-spin" />
                  ) : '✨ Sugerir'}
                </button>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Unidad medida base</label>
            <select name="baseUnitOfMeasure" value={formData.baseUnitOfMeasure} onChange={handleInputChange} className="w-full p-2 border border-gray-300 rounded">
              {units.map(u => <option key={u} value={u}>{u}</option>)}
            </select>
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Coste unitario</label>
            <input 
              type="number" 
              name="unitCost" 
              value={formData.unitCost} 
              onChange={handleInputChange} 
              readOnly={!isAdmin} 
              className={`w-full p-2 border rounded ${!isAdmin ? 'bg-gray-100 cursor-not-allowed text-gray-400' : 'border-gray-300'}`} 
            />
          </div>

          <div className="flex justify-between col-span-full mt-6 border-t pt-4">
            <button onClick={() => setStep(2)} className="px-6 py-2 border border-gray-300 rounded text-gray-600 hover:bg-gray-50">Atrás</button>
            <div className="space-x-4">
                <button onClick={onCancel} className="px-6 py-2 text-red-600 hover:bg-red-50 rounded">Cancelar</button>
                <button onClick={validateAndSave} disabled={!isDescriptionValid} className="px-8 py-2 bg-blue-600 text-white font-bold rounded shadow-lg hover:bg-blue-700 disabled:opacity-50">
                  Crear Producto
                </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProductForm;

import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { 
  ProductType, 
  CostingMethod, 
  Product,
  Manufacturer,
  ItemCategory,
  ExternalProduct
} from '../types';

interface ProductFormProps {
  onSave: (product: Product) => void;
  onCancel: () => void;
  existingProducts: Product[];
  externalProducts: ExternalProduct[];
  manufacturers: Manufacturer[];
  categories: ItemCategory[];
  units: string[];
  isAdmin: boolean;
}

const ProductForm: React.FC<ProductFormProps> = ({ 
  onSave, 
  onCancel, 
  existingProducts,
  externalProducts,
  manufacturers,
  categories,
  units,
  isAdmin
}) => {
  const [step, setStep] = useState(1);
  const [isSuggesting, setIsSuggesting] = useState(false);

  const [formData, setFormData] = useState<Partial<Product>>({
    type: ProductType.FABRICANTE,
    baseUnitOfMeasure: units[0] || 'UD',
    inventoryPostingGroup: 'MERCADERÍA', 
    genProdPostingGroup: 'MERCADERÍA',
    vatProdPostingGroup: 'IVA21',        
    costingMethod: CostingMethod.FIFO,
    unitPrice: 0,
    unitCost: 0,
    dimensionCode: 'GASTOS',            
    dimensionValueCode: 'MATERIAL',
    valuePosting: 'Mismo código',
    description: ''
  });

  const [manufacturerRef, setManufacturerRef] = useState('');
  const [descriptionTouched, setDescriptionTouched] = useState(false);
  const [categoryTouched, setCategoryTouched] = useState(false);

  useEffect(() => {
    let prefix = '';
    if (formData.type === ProductType.FABRICANTE && formData.manufacturerCode) {
      prefix = formData.manufacturerCode.substring(0, 3).toUpperCase();
    } else if (formData.type === ProductType.GENERICO && formData.itemCategoryCode) {
      prefix = `G${formData.itemCategoryCode.substring(0, 3).toUpperCase()}`;
    }

    if (prefix) {
      const allExistingNumbers = [
        ...existingProducts.map(p => p.no),
        ...externalProducts.map(p => p.no)
      ];

      const matching = allExistingNumbers.filter(no => no.startsWith(prefix));
      let nextNumber = 1;

      if (matching.length > 0) {
        const numbers = matching.map(no => {
          const numPart = no.substring(prefix.length);
          return parseInt(numPart, 10) || 0;
        });
        nextNumber = Math.max(...numbers) + 1;
      }

      const formattedNumber = nextNumber.toString().padStart(4, '0');
      setFormData(prev => ({ ...prev, no: `${prefix}${formattedNumber}` }));
    } else {
      setFormData(prev => ({ ...prev, no: '' }));
    }
  }, [formData.type, formData.manufacturerCode, formData.itemCategoryCode, existingProducts, externalProducts]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    let processedValue: any = value;
    if (name === 'description') processedValue = value.toUpperCase();
    if (name === 'unitPrice' || name === 'unitCost') processedValue = parseFloat(value) || 0;
    setFormData(prev => ({ ...prev, [name]: processedValue }));
  };

  const handleSuggestDescription = async () => {
    if (!manufacturerRef) return;

    const manufacturerName = manufacturers.find(m => m.code === formData.manufacturerCode)?.name || '';

    setIsSuggesting(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Actúa como un experto en suministros eléctricos e industriales. 
Identifica el producto del fabricante "${manufacturerName}" con referencia "${manufacturerRef}".
Genera una descripción técnica profesional para un catálogo ERP siguiendo exactamente este estilo de ejemplo: "INTERRUPTOR DIFERENCIAL ACTI9 IID, 2 POLOS, 40A, 30MA, CLASE A-SI".

REGLAS OBLIGATORIAS:
1. Comienza con el NOMBRE DEL PRODUCTO seguido de la GAMA/MODELO.
2. Añade las ESPECIFICACIONES TÉCNICAS (polos, amperaje, protección, etc.) separadas por COMAS.
3. No utilices artículos (el, la, los) ni introducciones.
4. TODO EN MAYÚSCULAS.
5. Devuelve ÚNICAMENTE el texto de la descripción.`,
      });

      const suggestedText = response.text?.trim().toUpperCase();
      if (suggestedText) {
        setFormData(prev => ({ ...prev, description: suggestedText }));
      }
    } catch (error) {
      console.error("Error suggesting description:", error);
      alert("No se pudo obtener una sugerencia. Verifique la referencia o su conexión.");
    } finally {
      setIsSuggesting(false);
    }
  };

  const validateAndSave = () => {
    const desc = formData.description?.trim();
    if (!desc) return;
    let finalDescription = desc;
    if (formData.type === ProductType.FABRICANTE && manufacturerRef) {
        const refSuffix = ` REF. ${manufacturerRef}`;
        if (!finalDescription.endsWith(refSuffix)) finalDescription = `${finalDescription}${refSuffix}`;
    }
    const completeProduct: Product = {
      ...formData as Product,
      description: finalDescription,
      manufacturerRef: manufacturerRef,
      inventoryPostingGroup: 'MERCADERÍA',
      vatProdPostingGroup: 'IVA21',
      dimensionCode: 'GASTOS'
    };
    onSave(completeProduct);
  };

  const checkDuplicateRef = () => {
    if (formData.type !== ProductType.FABRICANTE || !manufacturerRef) return false;
    const searchStr = `REF. ${manufacturerRef.toUpperCase()}`;
    const inExisting = existingProducts.some(p => 
      p.description.toUpperCase().includes(searchStr) || 
      (p.manufacturerRef && p.manufacturerRef.toUpperCase() === manufacturerRef.toUpperCase())
    );
    const inExternal = externalProducts.some(p => p.description.toUpperCase().includes(searchStr));
    return inExisting || inExternal;
  };

  const isDuplicateRef = checkDuplicateRef();
  const isDescriptionValid = formData.description && formData.description.trim().length > 0;
  const isCategoryValid = !!formData.itemCategoryCode;
  const isManufacturerValid = formData.type === ProductType.GENERICO || !!formData.manufacturerCode;
  const isRefValid = formData.type === ProductType.GENERICO || (!!manufacturerRef && !isDuplicateRef);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between mb-8 px-4">
        {[1, 2, 3].map((s) => (
          <div key={s} className="flex items-center">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold ${step === s ? 'bg-blue-600 text-white' : step > s ? 'bg-green-500 text-white' : 'bg-gray-200 text-gray-600'}`}>
              {s}
            </div>
            {s < 3 && <div className={`h-1 w-12 mx-2 ${step > s ? 'bg-green-500' : 'bg-gray-200'}`} />}
          </div>
        ))}
      </div>

      {step === 1 && (
        <div className="space-y-4">
          <h4 className="text-lg font-medium text-gray-700 text-center">Seleccione Tipo de Producto</h4>
          <div className="grid grid-cols-2 gap-4">
            <button
              onClick={() => { setFormData({ ...formData, type: ProductType.FABRICANTE }); setStep(2); }}
              className={`p-6 border-2 rounded-xl text-left transition-all ${formData.type === ProductType.FABRICANTE ? 'border-blue-600 bg-blue-50' : 'border-gray-200 hover:border-blue-300'}`}
            >
              <div className="text-xl font-bold text-blue-700">Fabricante</div>
              <p className="text-sm text-gray-500 mt-1">Requiere referencia externa.</p>
            </button>
            <button
              onClick={() => { setFormData({ ...formData, type: ProductType.GENERICO }); setStep(2); }}
              className={`p-6 border-2 rounded-xl text-left transition-all ${formData.type === ProductType.GENERICO ? 'border-blue-600 bg-blue-50' : 'border-gray-200 hover:border-blue-300'}`}
            >
              <div className="text-xl font-bold text-blue-700">Genérico</div>
              <p className="text-sm text-gray-500 mt-1">Categoría general estándar.</p>
            </button>
          </div>
        </div>
      )}

      {step === 2 && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Fabricante (Tabla 5720) {formData.type === ProductType.FABRICANTE && <span className="text-red-500">*</span>}</label>
            <select
              name="manufacturerCode"
              value={formData.manufacturerCode || ''}
              onChange={handleInputChange}
              className="w-full p-2 border border-gray-300 rounded focus:ring-2 focus:ring-blue-500 outline-none"
              disabled={formData.type === ProductType.GENERICO}
            >
              <option value="">Seleccione fabricante...</option>
              {manufacturers.map(m => <option key={m.code} value={m.code}>{m.code} - {m.name}</option>)}
            </select>
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Categoría (Tabla 5722) <span className="text-red-500">*</span></label>
            <select
              name="itemCategoryCode"
              value={formData.itemCategoryCode || ''}
              onBlur={() => setCategoryTouched(true)}
              onChange={handleInputChange}
              className={`w-full p-2 border rounded focus:ring-2 focus:ring-blue-500 outline-none ${categoryTouched && !isCategoryValid ? 'border-red-500 bg-red-50' : 'border-gray-300'}`}
              required
            >
              <option value="">Seleccione categoría...</option>
              {categories.map(c => <option key={c.code} value={c.code}>{c.code} - {c.description}</option>)}
            </select>
            {categoryTouched && !isCategoryValid && (
              <p className="text-[10px] text-red-500 font-bold">La selección de categoría es obligatoria.</p>
            )}
          </div>

          {formData.type === ProductType.FABRICANTE && (
            <div className="space-y-2 col-span-full">
              <label className="block text-sm font-semibold text-gray-600">Nro. de Referencia del Fabricante *</label>
              <input
                type="text"
                value={manufacturerRef}
                onChange={(e) => setManufacturerRef(e.target.value.toUpperCase())}
                placeholder="Ej: REF-12345"
                className={`w-full p-2 border rounded focus:ring-2 outline-none transition-colors ${isDuplicateRef ? 'border-red-500 bg-red-50 focus:ring-red-200' : 'border-gray-300 focus:ring-blue-500'}`}
                required
              />
              {isDuplicateRef && (
                <div className="bg-red-100 border-l-4 border-red-500 p-2 mt-2">
                  <p className="text-xs text-red-700 font-bold uppercase">
                    ¡ATENCIÓN! Ya existe un artículo con esta referencia en el maestro local o externo.
                  </p>
                </div>
              )}
            </div>
          )}

          <div className="space-y-2 col-span-full">
            <label className="block text-sm font-semibold text-gray-600">No. (Código Correlativo Autogenerado)</label>
            <input
              type="text"
              readOnly
              value={formData.no || ''}
              className="w-full p-3 border border-blue-200 bg-blue-50 rounded text-blue-800 font-mono font-bold"
            />
          </div>

          <div className="flex justify-between col-span-full mt-4">
            <button onClick={() => setStep(1)} className="px-6 py-2 border border-gray-300 rounded text-gray-600 hover:bg-gray-50">Atrás</button>
            <button 
              onClick={() => setStep(3)} 
              disabled={!formData.no || !isCategoryValid || !isManufacturerValid || !isRefValid}
              className="px-6 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50 transition-all font-bold"
            >
              Siguiente
            </button>
          </div>
        </div>
      )}

      {step === 3 && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2 col-span-full">
            <label className="block text-sm font-semibold text-gray-600">Descripción (MAYÚSCULAS) *</label>
            <div className="flex gap-2">
              <input
                type="text"
                name="description"
                maxLength={100}
                value={formData.description || ''}
                onBlur={() => setDescriptionTouched(true)}
                onChange={handleInputChange}
                placeholder="DESCRIPCIÓN"
                className={`flex-1 p-2 border rounded focus:ring-2 focus:ring-blue-500 outline-none uppercase ${descriptionTouched && !isDescriptionValid ? 'border-red-500 bg-red-50' : 'border-gray-300'}`}
                required
              />
              {formData.type === ProductType.FABRICANTE && (
                <button
                  type="button"
                  onClick={handleSuggestDescription}
                  disabled={!manufacturerRef || isSuggesting}
                  className="bg-blue-50 text-blue-700 px-4 py-2 rounded border border-blue-200 font-bold text-xs hover:bg-blue-100 disabled:opacity-50 transition-all flex items-center gap-2"
                  title="Sugerir descripción usando IA"
                >
                  {isSuggesting ? (
                    <div className="w-4 h-4 border-2 border-blue-700 border-t-transparent rounded-full animate-spin" />
                  ) : '✨ Sugerir'}
                </button>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Unidad medida base</label>
            <select name="baseUnitOfMeasure" value={formData.baseUnitOfMeasure} onChange={handleInputChange} className="w-full p-2 border border-gray-300 rounded">
              {units.map(u => <option key={u} value={u}>{u}</option>)}
            </select>
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Coste unitario</label>
            <input 
              type="number" 
              name="unitCost" 
              value={formData.unitCost} 
              onChange={handleInputChange} 
              readOnly={!isAdmin} 
              className={`w-full p-2 border rounded ${!isAdmin ? 'bg-gray-100 cursor-not-allowed text-gray-400' : 'border-gray-300'}`} 
            />
          </div>

          <div className="flex justify-between col-span-full mt-6 border-t pt-4">
            <button onClick={() => setStep(2)} className="px-6 py-2 border border-gray-300 rounded text-gray-600 hover:bg-gray-50">Atrás</button>
            <div className="space-x-4">
                <button onClick={onCancel} className="px-6 py-2 text-red-600 hover:bg-red-50 rounded">Cancelar</button>
                <button onClick={validateAndSave} disabled={!isDescriptionValid} className="px-8 py-2 bg-blue-600 text-white font-bold rounded shadow-lg hover:bg-blue-700 disabled:opacity-50">
                  Crear Producto
                </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProductForm;

export enum ProductType {
  FABRICANTE = 'Fabricante',
  GENERICO = 'Genérico'
}

export enum CostingMethod {
  FIFO = 'FIFO',
  LIFO = 'LIFO',
  AVERAGE = 'Media',
  SPECIFIC = 'Específico',
  STANDARD = 'Estándar'
}

export interface ItemCategory {
  code: string;
  description: string;
}

export interface Manufacturer {
  code: string;
  name: string;
}

export interface ExternalProduct {
  no: string;
  description: string;
}

export interface BCConfig {
  tenantId: string;
  environment: string;
  companyId: string;
  clientId: string;
  clientSecret: string;
  isConnected: boolean;
}

export interface Product {
  no: string;
  description: string;
  baseUnitOfMeasure: string;
  type: ProductType;
  inventoryPostingGroup: string;
  unitPrice: number;
  costingMethod: CostingMethod;
  unitCost: number;
  genProdPostingGroup: string;
  vatProdPostingGroup: string;
  manufacturerCode: string;
  itemCategoryCode: string;
  dimensionCode: string;
  dimensionValueCode: string;
  valuePosting: string;
  manufacturerRef?: string;
}

export enum UserRole {
  ADMIN = 'Administrador',
  TECNICO = 'Técnico',
  COMPRAS = 'Compras'
}

export interface RolePermissions {
  canCreateProduct: boolean;
  canManageMasterData: boolean;
}

export interface AppSettings {
  manufacturers: Manufacturer[];
  categories: ItemCategory[];
  unitsOfMeasure: string[];
  permissions: Record<UserRole, RolePermissions>;
  bcConfig?: BCConfig;
}

import React, { useState, useEffect } from 'react';
import { Product, UserRole, AppSettings, ExternalProduct, Manufacturer, ItemCategory, BCConfig } from './types';
import Modal from './components/Modal';
import ProductForm from './components/ProductForm';
import Settings from './components/Settings';
import ExternalProducts from './components/ExternalProducts';
import ReferenceInspection from './components/ReferenceInspection';
import { ITEM_CATEGORIES, MANUFACTURERS, UNITS_OF_MEASURE } from './constants';

const DEFAULT_BC_CONFIG: BCConfig = {
  tenantId: '',
  environment: 'production',
  companyId: '',
  clientId: '',
  clientSecret: '',
  isConnected: false
};

const DEFAULT_SETTINGS: AppSettings = {
  manufacturers: MANUFACTURERS,
  categories: ITEM_CATEGORIES,
  unitsOfMeasure: UNITS_OF_MEASURE,
  permissions: {
    [UserRole.ADMIN]: { canCreateProduct: true, canManageMasterData: true },
    [UserRole.TECNICO]: { canCreateProduct: true, canManageMasterData: false },
    [UserRole.COMPRAS]: { canCreateProduct: false, canManageMasterData: false },
  },
  bcConfig: DEFAULT_BC_CONFIG
};

const App: React.FC = () => {
  const [activeView, setActiveView] = useState<'products' | 'bc' | 'inspection' | 'settings'>('products');
  const [currentUser, setCurrentUser] = useState<UserRole>(UserRole.ADMIN);
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('bc_products');
    return saved ? JSON.parse(saved) : [];
  });
  const [externalProducts, setExternalProducts] = useState<ExternalProduct[]>(() => {
    const saved = localStorage.getItem('bc_external_products');
    return saved ? JSON.parse(saved) : [];
  });
  const [settings, setSettings] = useState<AppSettings>(() => {
    const saved = localStorage.getItem('bc_settings');
    const parsed = saved ? JSON.parse(saved) : DEFAULT_SETTINGS;
    // Asegurar que bcConfig existe
    if (!parsed.bcConfig) parsed.bcConfig = DEFAULT_BC_CONFIG;
    return parsed;
  });
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    localStorage.setItem('bc_products', JSON.stringify(products));
  }, [products]);

  useEffect(() => {
    localStorage.setItem('bc_external_products', JSON.stringify(externalProducts));
  }, [externalProducts]);

  useEffect(() => {
    localStorage.setItem('bc_settings', JSON.stringify(settings));
  }, [settings]);

  const userPerms = settings.permissions[currentUser];

  const handleAddProduct = (newProduct: Product) => {
    setProducts(prev => [newProduct, ...prev]);
    setIsModalOpen(false);
  };

  const handleBulkManufacturers = (newManufacturers: Manufacturer[]) => {
    setSettings(prev => ({
      ...prev,
      manufacturers: newManufacturers
    }));
    alert(`${newManufacturers.length} fabricantes cargados correctamente.`);
  };

  const handleBulkCategories = (newCategories: ItemCategory[]) => {
    setSettings(prev => ({
      ...prev,
      categories: newCategories
    }));
    alert(`${newCategories.length} categorías cargadas correctamente.`);
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-20 font-sans">
      <div className="bg-gray-800 text-white text-[10px] py-1 px-4 flex justify-between items-center uppercase tracking-widest font-bold">
        <span>SISTEMA DE GESTIÓN DE PRODUCTOS BC</span>
        <div className="flex items-center gap-3">
          <span>PERFIL ACTUAL:</span>
          <select 
            value={currentUser} 
            onChange={(e) => {
              const role = e.target.value as UserRole;
              setCurrentUser(role);
              if (!settings.permissions[role].canManageMasterData && activeView === 'settings') setActiveView('products');
            }}
            className="bg-gray-700 text-white border-none text-[10px] rounded focus:ring-0"
          >
            {Object.values(UserRole).map(role => <option key={role} value={role}>{role}</option>)}
          </select>
        </div>
      </div>

      <header className="bg-white border-b border-gray-200 sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-4 h-20 flex items-center justify-between">
          <div className="flex items-center gap-8">
            <div>
              <h1 className="text-xl font-black text-green-600 leading-none">TECMELEC</h1>
              <span className="text-xs text-gray-400 font-bold uppercase">Alta de productos</span>
            </div>

            <nav className="flex gap-1 bg-gray-100 p-1 rounded-lg">
              <button 
                onClick={() => setActiveView('products')}
                className={`px-4 py-2 rounded-md text-sm font-bold transition-all ${activeView === 'products' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                Productos
              </button>
              <button 
                onClick={() => setActiveView('bc')}
                className={`px-4 py-2 rounded-md text-sm font-bold transition-all ${activeView === 'bc' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                Productos BC
              </button>
              <button 
                onClick={() => setActiveView('inspection')}
                className={`px-4 py-2 rounded-md text-sm font-bold transition-all ${activeView === 'inspection' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
              >
                Inspección
              </button>
              {userPerms.canManageMasterData && (
                <button 
                  onClick={() => setActiveView('settings')}
                  className={`px-4 py-2 rounded-md text-sm font-bold transition-all ${activeView === 'settings' ? 'bg-white text-blue-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                  Configuración
                </button>
              )}
            </nav>
          </div>

          {activeView === 'products' && userPerms.canCreateProduct && (
            <button
              onClick={() => setIsModalOpen(true)}
              className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-lg font-bold shadow-lg shadow-blue-200 flex items-center gap-2 transform active:scale-95 transition-all"
            >
              <span className="text-lg">+</span> Nuevo producto
            </button>
          )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto p-4 md:p-8">
        {activeView === 'products' && (
          <div className="space-y-6">
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead className="bg-gray-50 border-b border-gray-100">
                    <tr>
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-wider">No.</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-wider">Descripción</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-wider">Tipo</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-wider">Categoría</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-wider">Fabricante</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-400 uppercase tracking-wider">U.M.</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {products.length === 0 ? (
                      <tr>
                        <td colSpan={6} className="px-6 py-20 text-center text-gray-400">
                          <p>No hay productos registrados.</p>
                        </td>
                      </tr>
                    ) : (
                      products.map((p, idx) => (
                        <tr key={idx} className="hover:bg-blue-50/30 transition-colors">
                          <td className="px-6 py-4 font-mono text-sm text-blue-700 font-bold">{p.no}</td>
                          <td className="px-6 py-4 text-sm text-gray-800 uppercase font-medium">{p.description}</td>
                          <td className="px-6 py-4">
                            <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase ${p.type === 'Fabricante' ? 'bg-indigo-100 text-indigo-700' : 'bg-green-100 text-green-700'}`}>
                              {p.type}
                            </span>
                          </td>
                          <td className="px-6 py-4 text-sm text-gray-500 font-bold uppercase">{p.itemCategoryCode || '-'}</td>
                          <td className="px-6 py-4 text-sm text-gray-500 font-bold">{p.manufacturerCode || '-'}</td>
                          <td className="px-6 py-4 text-sm text-gray-500">{p.baseUnitOfMeasure}</td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeView === 'bc' && (
          <ExternalProducts 
            externalProducts={externalProducts} 
            onUploadProducts={setExternalProducts}
            onUploadManufacturers={handleBulkManufacturers}
            onUploadCategories={handleBulkCategories}
            onClearProducts={() => setExternalProducts([])}
            isAdmin={currentUser === UserRole.ADMIN}
            bcConfig={settings.bcConfig}
          />
        )}

        {activeView === 'inspection' && (
          <ReferenceInspection 
            products={products}
            externalProducts={externalProducts}
          />
        )}

        {activeView === 'settings' && (
          <Settings 
            settings={settings} 
            onUpdateSettings={setSettings} 
            currentRole={currentUser}
          />
        )}
      </main>

      <Modal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        title="Alta de Producto"
      >
        <ProductForm 
          onSave={handleAddProduct}
          onCancel={() => setIsModalOpen(false)}
          existingProducts={products}
          externalProducts={externalProducts}
          manufacturers={settings.manufacturers}
          categories={settings.categories}
          units={settings.unitsOfMeasure}
          isAdmin={currentUser === UserRole.ADMIN}
        />
      </Modal>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AppSettings, UserRole, Manufacturer, ItemCategory, BCConfig } from '../types';

interface SettingsProps {
  settings: AppSettings;
  onUpdateSettings: (settings: AppSettings) => void;
  currentRole: UserRole;
}

const Settings: React.FC<SettingsProps> = ({ settings, onUpdateSettings, currentRole }) => {
  const [activeTab, setActiveTab] = useState<'manufacturers' | 'categories' | 'units' | 'roles' | 'api'>('manufacturers');
  const [newItem, setNewItem] = useState({ code: '', name: '', desc: '', unit: '' });

  const [bcForm, setBcForm] = useState<BCConfig>(settings.bcConfig || {
    tenantId: '',
    environment: 'production',
    companyId: '',
    clientId: '',
    clientSecret: '',
    isConnected: false
  });

  const isEditable = currentRole === UserRole.ADMIN;

  const handleTogglePermission = (role: UserRole, permission: 'canCreateProduct' | 'canManageMasterData') => {
    if (!isEditable) return;
    const newSettings = { ...settings };
    newSettings.permissions[role][permission] = !newSettings.permissions[role][permission];
    onUpdateSettings(newSettings);
  };

  const addItem = (type: 'manufacturer' | 'category' | 'unit') => {
    const newSettings = { ...settings };
    if (type === 'manufacturer' && newItem.code && newItem.name) {
      newSettings.manufacturers.push({ code: newItem.code.toUpperCase(), name: newItem.name.toUpperCase() });
    } else if (type === 'category' && newItem.code && newItem.desc) {
      newSettings.categories.push({ code: newItem.code.toUpperCase(), description: newItem.desc.toUpperCase() });
    } else if (type === 'unit' && newItem.unit) {
      newSettings.unitsOfMeasure.push(newItem.unit.toUpperCase());
    }
    onUpdateSettings(newSettings);
    setNewItem({ code: '', name: '', desc: '', unit: '' });
  };

  const removeItem = (type: 'manufacturer' | 'category' | 'unit', index: number) => {
    if (!isEditable) return;
    const newSettings = { ...settings };
    if (type === 'manufacturer') newSettings.manufacturers.splice(index, 1);
    if (type === 'category') newSettings.categories.splice(index, 1);
    if (type === 'unit') newSettings.unitsOfMeasure.splice(index, 1);
    onUpdateSettings(newSettings);
  };

  const saveBCConfig = () => {
    onUpdateSettings({ ...settings, bcConfig: bcForm });
    alert("Configuración de Business Central guardada correctamente.");
  };

