                <div className={`flex items-center gap-2 px-3 py-1 rounded-full border text-xs font-bold ${bcForm.tenantId ? 'bg-green-50 text-green-700 border-green-200' : 'bg-amber-50 text-amber-700 border-amber-200'}`}>
