              onClick={() => setStep(3)} 
              disabled={!formData.no || !isCategoryValid || !isManufacturerValid || !isRefValid}
              className="px-6 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50 transition-all font-bold"
