              {units.map(u => <option key={u} value={u}>{u}</option>)}
            </select>
          </div>

          <div className="space-y-2">
            <label className="block text-sm font-semibold text-gray-600">Coste unitario</label>
            <input 
              type="number" 
              name="unitCost" 
              value={formData.unitCost} 
              onChange={handleInputChange} 
